const iterationLimited = /^Agent stopped due to max iterations\.?$/i.test(output);
if (iterationLimited) output = '';
let structured = null;
if (output.startsWith('{')) {
  try { structured = JSON.parse(output); } catch {}
}
const catalog = input.catalog || { available: false, tours: [], services: [], serviceCandidates: [] };
const reply = typeof structured?.reply === 'string' ? structured.reply.trim() : output;
const tourIds = Array.isArray(structured?.tourIds) ? structured.tourIds.filter(id => typeof id === 'string').slice(0, 9) : [];
const selectedTours = [];
for (const id of tourIds) {
  const tour = (catalog.tours || []).find(item => item.id === id);
  if (!tour || selectedTours.some(item => item.id === id)) continue;
  const days = Number.isInteger(Number(tour.days)) && Number(tour.days) > 0 ? Number(tour.days) : null;
  const price = Number.isFinite(Number(tour.cost)) && Number(tour.cost) >= 0 ? Number(tour.cost) : null;
  selectedTours.push({
    id: tour.id,
    name: String(tour.title || tour.name || '').slice(0, 120),
    destination: String(tour.destination || '').slice(0, 100),
    durationDays: days,
    durationNights: days === null ? null : Math.max(0, days - 1),
    price,
    currency: price === null ? null : 'VND',
    imageUrl: typeof (tour.imageUrl || tour.image || tour.image_url) === 'string' ? (tour.imageUrl || tour.image || tour.image_url) : null,
    highlights: Array.isArray(tour.highlights) ? tour.highlights.slice(0, 5) : (Array.isArray(tour.tags) ? tour.tags.slice(0, 5) : []),
    ecoLabels: [],
    bookingAvailable: true,
    rating: Number.isFinite(Number(tour.rating)) ? Number(tour.rating) : null
  });
}
function norm(value) {
  return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\u0111\u0110]/g, 'd').toLowerCase().trim();
}
function normalizeItinerary(raw) {
  if (!raw || typeof raw !== 'object' || !Array.isArray(raw.days)) return null;
  const expectedDestination = String(catalog.query?.destination || '').trim();
  const destination = String(raw.destination || expectedDestination).trim().slice(0, 100);
  if (!destination || (expectedDestination && norm(destination) !== norm(expectedDestination))) return null;
  const requestedDays = Number(norm(input.message).match(/\b(\d{1,2})\s*(?:ngay|day)\b/)?.[1]) || 0;
  const rawDays = raw.days.slice(0, 14);
  if (requestedDays && rawDays.length !== requestedDays) return null;
  const serviceCandidates = Array.isArray(catalog.serviceCandidates) ? catalog.serviceCandidates : [];
  let estimatedCost = 0;
  const days = rawDays.map(day => {
    const activities = Array.isArray(day?.activities) ? day.activities : [];
    return activities.slice(0, 12).map(activity => {
      const name = String(activity?.name || '').trim().slice(0, 140);
      if (!name) return null;
      const candidate = typeof activity.serviceId === 'string'
        ? serviceCandidates.find(service => service.id === activity.serviceId && service.status === 'active' && norm(service.destination) === norm(destination))
        : null;
      if (!candidate) return { name, time: /^([01]\d|2[0-3]):[0-5]\d$/.test(activity.time || '') ? activity.time : '08:00', cost: 0, carbon: 0, type: 'attraction', verified: false, serviceId: null };
      const cost = Number.isFinite(Number(candidate.cost)) && Number(candidate.cost) >= 0 ? Number(candidate.cost) : 0;
      const carbon = Number.isFinite(Number(candidate.carbon)) && Number(candidate.carbon) >= 0 ? Number(candidate.carbon) : 0;
      estimatedCost += cost;
      const type = candidate.type === 'stay' ? 'lodging' : candidate.type === 'food' ? 'dining' : candidate.type === 'transport' ? 'transport' : 'attraction';
      return { name: String(candidate.name || name).slice(0, 140), time: /^([01]\d|2[0-3]):[0-5]\d$/.test(activity.time || '') ? activity.time : '08:00', cost, carbon, type, verified: true, serviceId: candidate.id };
    }).filter(Boolean);
  });
  if (!days.some(day => day.length)) return null;
  return {
    name: String(raw.name || ('Lịch trình ' + destination)).slice(0, 120),
    destination,
    startDate: null,
    endDate: null,
    days,
    estimatedCost,
    assumptions: Array.isArray(raw.assumptions) ? raw.assumptions.filter(item => typeof item === 'string').slice(0, 6).map(item => item.slice(0, 180)) : []
  };
}
const itinerary = normalizeItinerary(structured?.itinerary);
const requestedType = structured?.type;
const type = ['text', 'tour_recommendations', 'itinerary_proposal', 'clarification'].includes(requestedType)
  ? requestedType
  : itinerary ? 'itinerary_proposal' : selectedTours.length ? 'tour_recommendations' : 'text';
const suggestedQuestions = Array.isArray(structured?.suggestedQuestions)
  ? structured.suggestedQuestions.filter(item => typeof item === 'string' && item.trim()).slice(0, 3).map(item => item.trim().slice(0, 120))
  : [];
const reason = ai.finishReason ?? ai.response_metadata?.finishReason;
const outputLimited = reason === 'MAX_TOKENS';
console.log(JSON.stringify({ event: 'greensteps_n8n_agent_performance', agentMs, success: Boolean(reply) }));
return [{ json: {
  success: Boolean(reply),
  reply,
  output: reply,
  ...(iterationLimited ? { code: 'CHAT_ITERATION_LIMIT' } : {}),
  sessionId: input.sessionId,
  mode: 'n8n-gemini-agent-v4-direct',
