  const data = $("Validate Input1").first().json;

  // Đọc tham số do AI Agent truyền vào
  const args =
    typeof query === "object" && query !== null
      ? query
      : (() => {
          try {
            return JSON.parse(query);
          } catch {
            return { search: String(query || "") };
          }
        })();

  // Chuẩn hóa tiếng Việt để tìm kiếm
  const norm = (s) =>
